        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      size: "default",
    },
  },
);

function PillButton({
  className,
  size = "default",
  render,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof pillButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="pill-button"
      data-size={size}
      className={cn(pillButtonVariants({ size, className }))}
      nativeButton={render ? false : nativeButton}
      render={render}
      {...props}
    />
  );
}

export { PillButton, pillButtonVariants };
export default PillButton;

